#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n, a, b;
        cin >> n >> a >> b;
        vector<string> grid(n);
        for (auto &row : grid) cin >> row;
        if (a == 0 && b == 0) {
            int answer = 0;
            for (const auto &row : grid)
                for (char c : row) answer += (c != 'W');
            cout << answer << '\n';
            continue;
        }
        const int inf = 1000000000;
        int answer = 0;
        bool possible = true;
        for (int row = 0; row < n && possible; ++row) {
            for (int col = 0; col < n; ++col) {
                if (row - b >= 0 && col - a >= 0) continue;
                int d0 = 0, d1 = inf;
                for (int x = row, y = col; x < n && y < n; x += b, y += a) {
                    int best = min(d0, d1);
                    char c = grid[x][y];
                    if (c == 'W') {
                        d0 = best;
                        d1 = inf;
                    } else if (c == 'G') {
                        d0 = d1;
                        d1 = min(inf, best + 1);
                    } else {
                        d0 = inf;
                        d1 = min(inf, d1 + 1);
                    }
                }
                int best = min(d0, d1);
                if (best == inf) {
                    possible = false;
                    break;
                }
                answer += best;
            }
        }
        cout << (possible ? answer : -1) << '\n';
    }
}
