    int distinct = 0;
    for (int i = 0; i < n; ++i) {
        int value;
        cin >> value;
        prefix[i] = distinct;
        if (frequency[value] == 0) ++distinct;
        ++frequency[value];
        second[value] = last[value];
        last[value] = i;
    }
    long long answer = 0;
    for (int value = 1; value <= n; ++value) {
        if (second[value] >= 0)
            answer += prefix[second[value]] - (frequency[value] >= 3 ? 1 : 0);
    }
    cout << answer << '\n';
}
