#include <iostream>
#include <vector>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for (int &x : a) cin >> x;
    for (int &x : b) cin >> x;
    int base = 0;
    for (int i = 0; i < n; ++i) base += (a[i] == b[i]);
    vector<long long> histogram(n + 1);
    for (int sum = 0; sum <= 2 * n - 2; ++sum) {
        int left = sum / 2, right = (sum + 1) / 2;
        int matches = base;
        while (left >= 0 && right < n) {
            if (left < right) {
                matches += (a[left] == b[right]) + (a[right] == b[left])
                         - (a[left] == b[left]) - (a[right] == b[right]);
            }
            ++histogram[matches];
            --left;
            ++right;
        }
    }
    for (long long count : histogram) cout << count << '\n';
}
